// writeStoreError answers the store's failure: a note that is not there, or
// not the caller's, is 404; anything else is 500 and goes to the log.
func writeStoreError(w http.ResponseWriter, err error) {
	if errors.Is(err, store.ErrNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found"})
		return
	}
	log.Printf("server: %v", err)
	writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
}
// Package store keeps the app's data: users, sessions, notes, tags and
// share links. sqlite.Open builds the Store the server holds.
package store

import (
	"errors"
	"time"
)

// ErrNotFound is what every getter answers for a row that is not there —
// including another user's note, which the API must show as 404.
var ErrNotFound = errors.New("store: not found")

// User is an account. PasswordHash is bcrypt; it never leaves the store in
// a User sent to a handler's answer.
type User struct {
	ID           int64
	Username     string
	PasswordHash string
	CreatedAt    time.Time
}

// Session is a login: Token is the cookie's value, Expires the instant the
// session stops being valid.
type Session struct {
	Token     string
	UserID    int64
	Expires   time.Time
	CreatedAt time.Time
}

// Note is one note of one user. Tags are the lower-cased names attached to
// it; Pinned orders it before all others in a listing.
type Note struct {
	ID        int64
	UserID    int64
	Title     string
	Body      string
	Tags      []string
	Pinned    bool
	CreatedAt time.Time
	UpdatedAt time.Time
}

// Share is a read-only link to a note. Token is 22 URL-safe characters;
// RevokedAt is nil while the link answers. ID names the link for revoking.
type Share struct {
	ID        int64
	Token     string
	NoteID    int64
	UserID    int64
	CreatedAt time.Time
	RevokedAt *time.Time
}

// TagCount is one tag of a user with the number of their notes carrying it.
type TagCount struct {
	Tag   string
	Count int
}

// ListNotesOptions narrows a listing. Empty values ask for everything.
type ListNotesOptions struct {
	// Tag keeps the notes carrying that tag (lower-cased).
	Tag string
	// Q is a case-insensitive substring of title or body.
	Q string
	// Page is 1-based; PageSize is the notes per page when greater than 0.
	Page     int
	PageSize int
}

// NotePage is one page of a listing with the total of matching notes.
type NotePage struct {
	Notes []Note
	Total int
}

// Store is the app's whole persistence contract. Every feature card gets
// this interface, never the sqlite type behind it.
type Store interface {
	CreateUser(username, passwordHash string) (*User, error)
	GetUserByUsername(username string) (*User, error)
	// GetUserByID answers the account of a session token, which names only
	// its user's id.
	GetUserByID(id int64) (*User, error)

	CreateSession(userID int64, token string, expires time.Time) (*Session, error)
	GetSession(token string) (*Session, error)
	DeleteSession(token string) error

	CreateNote(userID int64, title, body string, tags []string) (*Note, error)
	GetNote(noteID, userID int64) (*Note, error)
	ListNotes(userID int64, opts ListNotesOptions) (*NotePage, error)
	UpdateNote(noteID, userID int64, title, body string, tags []string) (*Note, error)
	DeleteNote(noteID, userID int64) error
	PinNote(noteID, userID int64) (*Note, error)
	UnpinNote(noteID, userID int64) (*Note, error)

	CreateShare(noteID, userID int64, token string) (*Share, error)
	GetShare(token string) (*Note, error)
	RevokeShare(shareID, userID int64) error

	ListTags(userID int64) ([]TagCount, error)

	Close() error
}

	return s.setPinned(noteID, userID, false)
}

func (s *sqliteStore) ListNotes(userID int64, opts ListNotesOptions) (*NotePage, error) {
	where := `n.user_id = ?`
	args := []any{userID}
	if tag := strings.ToLower(strings.TrimSpace(opts.Tag)); tag != "" {
		where += ` AND EXISTS (SELECT 1 FROM note_tags t WHERE t.note_id = n.id AND t.tag = ?)`
		args = append(args, tag)
	}
	if q := strings.TrimSpace(opts.Q); q != "" {
		where += ` AND (n.title LIKE '%' || ? || '%' ESCAPE '\' OR n.body LIKE '%' || ? || '%' ESCAPE '\')`
		like := escapeLike(q)
		args = append(args, like, like)
	}
	page := opts.Page
	if page < 1 {
		page = 1
	}
	size := opts.PageSize
	if size <= 0 {
		size = 20
	}

	total := 0
	if err := s.db.QueryRow(`SELECT count(*) FROM notes n WHERE `+where, args...).Scan(&total); err != nil {
		return nil, fmt.Errorf("store: count notes: %w", err)
	}
	rows, err := s.db.Query(`SELECT `+noteColumns+` FROM notes n WHERE `+where+`
		ORDER BY n.pinned DESC, n.updated_at DESC, n.id DESC LIMIT ? OFFSET ?`,
		append(args, size, (page-1)*size)...)
	if err != nil {
		return nil, fmt.Errorf("store: list notes: %w", err)
	}
	defer func() { _ = rows.Close() }()
	out := &NotePage{Total: total, Notes: []Note{}}
	for rows.Next() {
		n, err := s.scanNote(rows)
		if err != nil {
			return nil, fmt.Errorf("store: list notes: %w", err)
		}
		out.Notes = append(out.Notes, *n)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: list notes: %w", err)
	}
	for i := range out.Notes {
		tags, err := s.tagsOf(out.Notes[i].ID)
		if err != nil {
			return nil, err
		}
		out.Notes[i].Tags = tags
	}
	return out, nil
}

// escapeLike quotes the LIKE wildcards of a search term.
func escapeLike(s string) string {
	r := strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`)
	return r.Replace(s)
}

func (s *sqliteStore) CreateShare(noteID, userID int64, token string) (*Share, error) {
	res, err := s.exec(`INSERT INTO shares (note_id, user_id, token) VALUES (?, ?, ?)`, noteID, userID, token)
	if err != nil {
		return nil, err
	}
	id, err := res.LastInsertId()
	if err != nil {
		return nil, fmt.Errorf("store: share id: %w", err)
	}
	sh := &Share{Token: token, NoteID: noteID, UserID: userID, ID: id}
	var created string
	if err := s.db.QueryRow(`SELECT created_at FROM shares WHERE id = ?`, id).Scan(&created); err != nil {
		return nil, fmt.Errorf("store: get share: %w", err)
	}
	sh.CreatedAt = parseTime(created)
	return sh, nil
}

// GetShare answers the shared note for an active link: its id, title and
// body only. A revoked or unknown token, and a deleted note, are ErrNotFound.
func (s *sqliteStore) GetShare(token string) (*Note, error) {
	n := &Note{}
	err := s.db.QueryRow(`SELECT n.id, n.title, n.body FROM notes n
		JOIN shares h ON h.note_id = n.id
		WHERE h.token = ? AND h.revoked_at IS NULL`, token).Scan(&n.ID, &n.Title, &n.Body)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("store: get share: %w", err)
	}
	return n, nil
}

func (s *sqliteStore) RevokeShare(shareID, userID int64) error {
	res, err := s.exec(`UPDATE shares SET revoked_at = strftime('%Y-%m-%d %H:%M:%S','now')
		WHERE id = ? AND user_id = ? AND revoked_at IS NULL`, shareID, userID)
	if err != nil {
		return err
	}
	if n, err := res.RowsAffected(); err != nil {
		return fmt.Errorf("store: revoke: %w", err)
	} else if n == 0 {
		return ErrNotFound
	}
	return nil
}

func (s *sqliteStore) ListTags(userID int64) ([]TagCount, error) {
	rows, err := s.db.Query(`SELECT t.tag, count(*) FROM note_tags t
		JOIN notes n ON n.id = t.note_id
		WHERE n.user_id = ?
		GROUP BY t.tag ORDER BY t.tag`, userID)
	if err != nil {
		return nil, fmt.Errorf("store: list tags: %w", err)
	}
	defer func() { _ = rows.Close() }()
	out := []TagCount{}
	for rows.Next() {
		var tc TagCount
		if err := rows.Scan(&tc.Tag, &tc.Count); err != nil {
			return nil, fmt.Errorf("store: list tags: %w", err)
		}
		out = append(out, tc)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: list tags: %w", err)
	}
	return out, nil
}

func hostnameOf(host string) string {
	i := strings.LastIndexByte(host, ':')
	if i < 0 {
		return host
	}
	if j := strings.LastIndexByte(host, ']'); j >= 0 && j > i {
		return host[:j+1]
	}
	return host[:i]
}
