// TestCreateNoteWithTags is acceptance item A2 of the plan: the tags "Go",
// "go" and "work" of a new note come back as the two distinct lower-cased
// ones, GET /api/tags counts each at one note, and the note carries its id
// and both timestamps.
func TestCreateNoteWithTags(t *testing.T) {
	st := newStore(t)
	srv := httptest.NewServer(server.New(server.Config{Store: st}))
	defer srv.Close()
	as := login(t, st, "ada")

	status, body := do(t, as(http.MethodPost, srv.URL+"/api/notes", map[string]any{
		"title": "Release notes",
		"body":  "What shipped this week.",
		"tags":  []string{"Go", "go", "work"},
	}))
	if status != http.StatusCreated {
		t.Fatalf("POST /api/notes: %d %q, want 201", status, body)
	}
	created := decodeNote(t, body)
	if created.ID == 0 {
		t.Fatalf("the created note has no id: %q", body)
	}
	if got := strings.Join(created.Tags, ","); got != "go,work" {
		t.Errorf("the tags of the answer are %q, want go,work", got)
	}
	if created.CreatedAt == "" || created.UpdatedAt == "" {
		t.Errorf("the created note carries no timestamps: %q", body)
	}

	status, body = do(t, as(http.MethodGet, srv.URL+"/api/notes/"+strconv.FormatInt(created.ID, 10), nil))
	if status != http.StatusOK {
		t.Fatalf("GET /api/notes/%d: %d %q, want 200", created.ID, status, body)
	}
	read := decodeNote(t, body)
	if read.Title != "Release notes" || read.Body != "What shipped this week." {
		t.Errorf("GET /api/notes/%d answered %+v", created.ID, read)
	}
	if got := strings.Join(read.Tags, ","); got != "go,work" {
		t.Errorf("the stored tags are %q, want go,work", got)
	}

	status, body = do(t, as(http.MethodGet, srv.URL+"/api/tags", nil))
	if status != http.StatusOK {
		t.Fatalf("GET /api/tags: %d %q, want 200", status, body)
	}
	var listing struct {
		Tags []struct {
			Tag   string `json:"tag"`
			Count int    `json:"count"`
		} `json:"tags"`
	}
	if err := json.Unmarshal(body, &listing); err != nil {
		t.Fatalf("GET /api/tags answered %q: %v", body, err)
	}
	counts := map[string]int{}
	for _, tc := range listing.Tags {
		counts[tc.Tag] = tc.Count
	}
	if counts["go"] != 1 || counts["work"] != 1 {
		t.Errorf("GET /api/tags answered %q, want go with 1 and work with 1", body)
	}
	if len(listing.Tags) != 2 {
		t.Errorf("GET /api/tags answered %d tags, want 2: %q", len(listing.Tags), body)
	}
}

-- init: the tables of accounts, notes, tags and share links.
-- Times are UTC text in the RFC 3339 form SQLite's datetime() writes.

CREATE TABLE users (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    username      TEXT NOT NULL UNIQUE COLLATE BINARY,
    password_hash TEXT NOT NULL,
    created_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE sessions (
    token      TEXT PRIMARY KEY,
    user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX sessions_user_idx ON sessions(user_id);

CREATE TABLE notes (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    title      TEXT NOT NULL,
    body       TEXT NOT NULL DEFAULT '',
