+package server_test
+
+import (
+	"encoding/json"
+	"net/http"
+	"net/http/httptest"
+	"strconv"
+	"testing"
+	"time"
+
+	"git.aisoftwarefactory.world/notes/notes/internal/server"
+	"git.aisoftwarefactory.world/notes/notes/internal/store"
+)
+
+// listing is what GET /api/notes answers: one page of notes with the total
+// of notes matching the filter, and the page it was asked for.
+type listing struct {
+	Notes []note `json:"notes"`
+	Total int    `json:"total"`
+	Page  int    `json:"page"`
+}
+
+func decodeListing(t *testing.T, body []byte) listing {
+	t.Helper()
+	l := listing{}
+	if err := json.Unmarshal(body, &l); err != nil {
+		t.Fatalf("GET /api/notes answered no listing JSON: %q: %v", body, err)
+	}
+	return l
+}
+
+// getListing asks the API for a page of the user's notes and decodes it.
+func getListing(t *testing.T, as func(method, path string, body any) *http.Request, url, query string) listing {
+	t.Helper()
+	path := url + "/api/notes"
+	if query != "" {
+		path += "?" + query
+	}
+	status, body := do(t, as(http.MethodGet, path, nil))
+	if status != http.StatusOK {
+		t.Fatalf("GET %s: %d %q, want 200", path, status, body)
+	}
+	return decodeListing(t, body)
+}
+
+// titlesOf names a listing's notes in their own order.
+func titlesOf(l listing) []string {
+	out := make([]string, 0, len(l.Notes))
+	for _, n := range l.Notes {
+		out = append(out, n.Title)
+	}
+	return out
+}
+
+// TestPagination is acceptance item A5 of the plan: with 25 notes the first
+// page carries 20 of them and says the total is 25, the second page carries
+// the remaining 5, and an edit of the oldest note brings it to the front.
+func TestPagination(t *testing.T) {
+	st := newStore(t)
+	srv := httptest.NewServer(server.New(server.Config{Store: st}))
+	defer srv.Close()
+	as := login(t, st, "ada")
+
+	user, err := st.GetUserByUsername("ada")
+	if err != nil {
+		t.Fatal(err)
+	}
+	base := time.Now().UTC().Add(-time.Hour).Truncate(time.Second)
+	ids := make([]int64, 0, 25)
+	for i := range 25 {
+		note, err := st.CreateNote(user.ID, "note "+strconv.Itoa(i), "body "+strconv.Itoa(i), nil)
+		if err != nil {
+			t.Fatal(err)
+		}
