	db *sql.DB

	// stampMu guards lastStamp, the newest note timestamp the store wrote.
	stampMu   sync.Mutex
	lastStamp time.Time
}''')

s=s.replace('''// monotonic is the last timestamp the store wrote into a note. SQLite's
// CURRENT_TIMESTAMP only changes with the second, so several writes inside one
// second would share a timestamp and no listing ordered by it could tell the
// first edit of a note from the next; each write therefore takes at least the
// second after the one before it.
var monotonic struct {
	mu   sync.Mutex
	last time.Time
}

// newerStamp answers the timestamp to give a row now: the store's current UTC
// second, or the second after the last stamp when the clock has not caught up.
func (s *sqliteStore) newerStamp() time.Time {
	now := time.Now().UTC().Truncate(time.Second)
	monotonic.mu.Lock()
	defer monotonic.mu.Unlock()
	if !now.After(monotonic.last) {
		now = monotonic.last.Add(time.Second)
	}
	monotonic.last = now
	return now
}''','''// seedStamp learns the newest note timestamp already in the database, so a
// reopened store never stamps an edit older than the row it edits.
func (s *sqliteStore) seedStamp() error {
	var newest string
