// SQLite's CURRENT_TIMESTAMP only turns with the second, so writes inside one
// second would share a timestamp and a listing ordered by updated_at could not
// tell an edit from the rows it has to come before.
func (s *sqliteStore) newerStamp() time.Time {
	now := time.Now().UTC().Truncate(time.Second)
	s.stampMu.Lock()
	defer s.stampMu.Unlock()
	if !now.After(s.lastStamp) {
		now = s.lastStamp.Add(time.Second)
