+}
+
+// listNotes answers the user's notes, pinned first and each group by the
+// most recently updated, ?page=n pages of pageSize notes, narrowed by
+// ?tag=<tag> and ?q=<text>, which combine. A page that is no number is 400.
+func (s *server) listNotes(w http.ResponseWriter, r *http.Request) {
+	userID, ok := s.userOf(r)
+	if !ok {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	page := 1
+	if raw := r.URL.Query().Get("page"); raw != "" {
