+		Tag:      r.URL.Query().Get("tag"),
+		Q:        r.URL.Query().Get("q"),
+		Page:     page,
+		PageSize: pageSize,
+	})
+	if err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	out := notePageJSON{
+		Notes: make([]noteJSON, 0, len(result.Notes)),
+		Total: result.Total,
+		Page:  page,
+	}
+	for i := range result.Notes {
+		out.Notes = append(out.Notes, noteToJSON(&result.Notes[i]))
+	}
+	writeJSON(w, http.StatusOK, out)
+}
+
+// setPinned answers POST and DELETE /api/notes/<id>/pin with the note as it
+// is now, so the client sees its own ordering change without a second read.
+func (s *server) setPinned(w http.ResponseWriter, r *http.Request, pinned bool) {
+	userID, ok := s.userOf(r)
+	if !ok {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	noteID, ok := noteIDFrom(w, r)
+	if !ok {
+		return
+	}
+	var (
+		note *store.Note
+		err  error
+	)
+	if pinned {
+		note, err = s.store.PinNote(noteID, userID)
+	} else {
+		note, err = s.store.UnpinNote(noteID, userID)
+	}
+	if err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	writeJSON(w, http.StatusOK, noteToJSON(note))
+}
+
+func (s *server) pinNote(w http.ResponseWriter, r *http.Request) {
+	s.setPinned(w, r, true)
+}
+
+func (s *server) unpinNote(w http.ResponseWriter, r *http.Request) {
+	s.setPinned(w, r, false)
+}
