test('the pin toggle moves a note to the top and back', async () => {
  let pinnedId = 0
  server(
    [
      { id: 1, title: 'older', updated_at: '2026-10-01T09:00:00Z' },
      { id: 2, title: 'newer', updated_at: '2026-10-01T10:00:00Z' },
    ],
    (id, pinned) => {
      if (pinned) pinnedId = id
    },
  )
  renderAt('/notes')
  await waitFor(() => expect(screen.getAllByRole('listitem')[0].textContent).toContain('newer'))

  fireEvent.click(screen.getAllByRole('button', { name: 'Pin' })[0])
  await waitFor(() => expect(pinnedId).toBe(1))
  await waitFor(() => {
    const first = screen.getAllByRole('listitem')[0]
    expect(first.textContent).toContain('older')
    expect(first.className).toContain('pinned')
    expect(first.textContent).toContain('pinned')
  })

  fireEvent.click(screen.getByRole('button', { name: 'Unpin' }))
  await waitFor(() => expect(pinnedId).toBe(0))
  await waitFor(() => expect(screen.getAllByRole('listitem')[0].textContent).toContain('newer'))
  expect(screen.getAllByRole('listitem')[0].className).not.toContain('pinned')
})

