+
+// notePageJSON is one page of a listing: its notes and the total of notes
+// matching the filter, whatever page was asked for.
+type notePageJSON struct {
+	Notes []noteJSON `json:"notes"`
+	Total int        `json:"total"`
+	Page  int        `json:"page"`
+}
+
+// listNotes answers the user's notes, pinned first and each group by the
+// most recently updated, ?page=n pages of pageSize notes, narrowed by
+// ?tag=<tag> and ?q=<text>, which combine. A page that is no number is 400.
+func (s *server) listNotes(w http.ResponseWriter, r *http.Request) {
+	userID, ok := s.userOf(r)
+	if !ok {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	page := 1
+	if raw := r.URL.Query().Get("page"); raw != "" {
+		n, err := strconv.Atoi(raw)
+		if err != nil || n < 1 {
+			writeValidationError(w, map[string]string{"page": "must be a positive whole number"})
+			return
+		}
+		page = n
+	}
+	result, err := s.store.ListNotes(userID, store.ListNotesOptions{
+		Tag:      r.URL.Query().Get("tag"),
+		Q:        r.URL.Query().Get("q"),
+		Page:     page,
+		PageSize: pageSize,
+	})
+	if err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	out := notePageJSON{
+		Notes: make([]noteJSON, 0, len(result.Notes)),
+		Total: result.Total,
+		Page:  page,
+	}
+	for i := range result.Notes {
+		out.Notes = append(out.Notes, noteToJSON(&result.Notes[i]))
+	}
+	writeJSON(w, http.StatusOK, out)
+}
+
+// setPinned answers POST and DELETE /api/notes/<id>/pin with the note as it
+// is now, so the client sees its own ordering change without a second read.
+func (s *server) setPinned(w http.ResponseWriter, r *http.Request, pinned bool) {
+	userID, ok := s.userOf(r)
+	if !ok {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	noteID, ok := noteIDFrom(w, r)
+	if !ok {
+		return
+	}
+	var (
+		note *store.Note
+		err  error
+	)
+	if pinned {
+		note, err = s.store.PinNote(noteID, userID)
+	} else {
+		note, err = s.store.UnpinNote(noteID, userID)
+	}
+	if err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	writeJSON(w, http.StatusOK, noteToJSON(note))
+}
+
+func (s *server) pinNote(w http.ResponseWriter, r *http.Request) {
+	s.setPinned(w, r, true)
+}
+
+func (s *server) unpinNote(w http.ResponseWriter, r *http.Request) {
+	s.setPinned(w, r, false)
+}
