import { useCallback, useEffect, useMemo, useState } from 'react'
import type { FormEvent } from 'react'
import { Link, useSearchParams } from 'react-router'

// The listing's page size: what one page of GET /api/notes carries.
const PAGE_SIZE = 20

type Note = {
  id: number
  title: string
  body: string
  tags: string[]
  pinned: boolean
  created_at: string
  updated_at: string
}

type TagCount = { tag: string; count: number }

type Listing = { notes: Note[]; total: number; page: number }

// searchParamsOf reads the box, the dropdown and the page off the url, so a
// listing can be shared or reloaded and the browser's back button works.
type Filters = { q: string; tag: string; page: number }

function filtersFrom(params: URLSearchParams): Filters {
  const raw = Number.parseInt(params.get('page') ?? '1', 10)
  return {
    q: params.get('q') ?? '',
    tag: params.get('tag') ?? '',
    page: Number.isFinite(raw) && raw > 0 ? raw : 1,
  }
}

function queryOf(filters: Filters): string {
  const params = new URLSearchParams()
  if (filters.q) params.set('q', filters.q)
  if (filters.tag) params.set('tag', filters.tag)
  if (filters.page > 1) params.set('page', String(filters.page))
  const query = params.toString()
  return query ? `?${query}` : ''
}

const listingPath = '/api/notes'

// pagesOf answers how many pages a total of notes fills at the API's page
// size, which the server keeps to whatever the client asks about.
export function pagesOf(total: number): number {
  return Math.max(1, Math.ceil(total / PAGE_SIZE))
}

async function readError(res: Response): Promise<string> {
  try {
    const answer = (await res.json()) as { error?: string }
    return answer.error || `${res.status}`
  } catch {
    return `${res.status}`
  }
}
